    val suggestedTitle: String? = null,
    val doneWhen: List<DoneItem> = emptyList(),
    val approvals: List<String> = emptyList(),
    val approvalsNeeded: Long,
    val reviews: List<String> = emptyList(),
    val reviewsNeeded: Long,
