)

@Serializable
data class StatsFindingOutcomes(
    val fixed: Long,
    val disputed: Long,
    val open: Long,
    /** Findings of tasks that are gone, whose status wasn't kept. */
    val unknown: Long,
    /** Rounds from the one that raised a finding to the one that saw it fixed. */
