)

/** Findings raised on one agent's work. */
@Serializable
data class StatsFindingAgent(
    val agent: String,
    val rounds: Long,
    val findings: Long,
    val serious: Long,
    val perRound: Double? = null,
)

@Serializable
data class StatsFindingRow(
    val task: String,
    val title: String,
    val kind: FindingKind,
    val severity: Severity,
    val text: String,
    val file: String? = null,
