/** The factory's statistics over the last `days`: what people had to step in for, for tuning prompts and loops. Admins only. */
@Serializable
data class StatsSummary(
    val days: Long,
    val goal: String? = null,
    val since: Long,
    val generatedAt: Long,
    /** Rows in the window worked out from older tasks' history rather than recorded as they happened. */
    val inferred: Long,
    val totals: StatsTotals,
    /** medianMs: how long they stayed up. */
    val handsByReason: List<StatsCount> = emptyList(),
    val findingsByKind: List<StatsCount> = emptyList(),
    val findingsBySeverity: List<StatsCount> = emptyList(),
    val restartsByCause: List<StatsCount> = emptyList(),
    val prompts: List<StatsCount> = emptyList(),
    val reviewVerdicts: List<StatsCount> = emptyList(),
    val daily: List<StatsDay> = emptyList(),
    val goals: List<StatsGoalRow> = emptyList(),
    val agents: List<StatsAgentRow> = emptyList(),
    /** The tasks with the most touchpoints, most first. */
    val topTasks: List<StatsTaskRow> = emptyList(),
    val costTotal: StatsCostRow? = null,
    /** planner, builder, reviewer, … */
    val costByRole: List<StatsCostRow> = emptyList(),
    /** Keyed "agent · model". */
    val costByAgent: List<StatsCostRow> = emptyList(),
    /** The findings breakdown; none from a server older than it. */
    val findings: StatsFindings? = null,
)

/** Runner → server. */
@Serializable(with = RunnerMessage.Serializer::class)
sealed class RunnerMessage {
    /** First message on every connection, so a server that missed messages catches up. */
    @Serializable
    data class Hello(
        val runnerId: String,
        val hostname: String,
        val os: String,
        val arch: String,
        val version: String,
        val sessions: List<dev.maplefactory.wire.LiveSession> = emptyList(),
        /** Sessions that ended since the last connection, causes included. */
        val ended: List<dev.maplefactory.wire.SessionEnd> = emptyList(),
    ) : RunnerMessage()
    @Serializable
    data class Health(
        val health: dev.maplefactory.wire.Health,
    ) : RunnerMessage()
    @Serializable
    data class SessionOpened(
        val session: dev.maplefactory.wire.SessionInfo,
    ) : RunnerMessage()
    @Serializable
    data class SessionError(
        val id: String,
        val message: String,
    ) : RunnerMessage()
    @Serializable
    data class SessionEnded(
        val end: dev.maplefactory.wire.SessionEnd,
    ) : RunnerMessage()
    @Serializable
    data class SessionActivity(
        val id: String,
        val activity: dev.maplefactory.wire.Activity,
    ) : RunnerMessage()
    /** The screen and scrollback asked for by `session.replay`, as bytes that repaint a fresh terminal. */
    @Serializable
    data class SessionReplay(
        val id: String,
        val nonce: String,
        /** Base64. */
        val data: String,
    ) : RunnerMessage()
    @Serializable
    data class UpdateStatus(
        val state: String,
        val version: String? = null,
        val message: String? = null,
    ) : RunnerMessage()
    /** How an `agent.login` is going. */
    @Serializable
    data class AgentLoginStatus(
        val status: dev.maplefactory.wire.AgentLoginStatus,
    ) : RunnerMessage()
    /** Plan usage readings that changed (all of them again on reconnect). */
    @Serializable
    data class Usage(
        val agents: List<dev.maplefactory.wire.AgentUsage> = emptyList(),
    ) : RunnerMessage()
    /** A session's latest spend reading (again on reconnect, and once more just before it ends). */
    @Serializable
    data class SessionCost(
        val cost: dev.maplefactory.wire.SessionCost,
    ) : RunnerMessage()
    /** A tool call from an agent in one of this runner's sessions (or `tools/list`, for its tools). */
    @Serializable
    data class McpRequest(
        val reqId: String,
        val session: String,
        val tool: String,
        val args: JsonElement,
    ) : RunnerMessage()
    /** A task's worktree is made: where it came from. */
    @Serializable
    data class TaskStarted(
        val taskId: String,
        val repo: String? = null,
        val repoDir: String,
        val base: String,
        val project: String? = null,
    ) : RunnerMessage()
    @Serializable
    data class TaskFinished(
        val taskId: String,
        val ok: Boolean,
        /** app (a GitHub App token) or fallback (the machine's credentials). */
        val pushed: String? = null,
        val owner: String? = null,
        val repo: String? = null,
        val branch: String,
        val base: String? = null,
        val commit: String? = null,
        val reason: String? = null,
        val message: String? = null,
        /** The repo's checks that ran, in order; the last one failed when the finish stopped on a check (nothing committed or pushed). */
        val checks: List<dev.maplefactory.wire.CheckRun>? = null,
    ) : RunnerMessage()
    /** What a task's branch changes against its base: line counts per file and the unified patch. */
    @Serializable
    data class TaskDiff(
        val taskId: String,
        val ok: Boolean,
        val files: List<dev.maplefactory.wire.DiffStat> = emptyList(),
        val patch: String,
        val truncated: Boolean,
        val message: String? = null,
        /** The branch's commits, oldest first; none from runners that predate it. */
        val commits: List<dev.maplefactory.wire.DiffCommit>? = null,
    ) : RunnerMessage()
    @Serializable
    data class TaskMerged(
        val taskId: String,
        val ok: Boolean,
        val commit: String? = null,
        val message: String? = null,
        /** What became of the merged branch on origin: deleted, gone (already), moved (kept: it has commits that didn't merge) or `failed: <why>`. */
        val branch: String? = null,
    ) : RunnerMessage()
    /** How a dry-run merge of a task's branch into its base went: `clean`, or the `conflicts` paths. Nothing was changed. */
    @Serializable
    data class TaskMergeCheck(
        val taskId: String,
        /** The check ran; false: `message` says why not. */
        val ok: Boolean,
        val clean: Boolean,
        val conflicts: List<String> = emptyList(),
        val message: String? = null,
    ) : RunnerMessage()
    /** How `task.handoff` went: the branch is on origin at `commit`, or `message` says why not. */
    @Serializable
    data class TaskHandedOff(
        val taskId: String,
        val ok: Boolean,
        val pushed: String? = null,
        val commit: String? = null,
        val message: String? = null,
    ) : RunnerMessage()
    /** What a draft's agent is doing (a `tool` line, the default) or saying (`text`). */
    @Serializable
    data class DraftProgress(
        val id: String,
        val text: String,
        val kind: dev.maplefactory.wire.DraftLineKind? = null,
    ) : RunnerMessage()
    /** A draft's agent finished: its last message, or why it couldn't. */
    @Serializable
    data class DraftDone(
        val id: String,
        val output: String? = null,
        val error: String? = null,
    ) : RunnerMessage()
    /** A line about setting a task's worktree up or cleaning it up (a worktree script starting or finishing), for its timeline. */
    @Serializable
    data class TaskProgress(
        val taskId: String,
        val text: String,
    ) : RunnerMessage()
    @Serializable
    data class TaskCleaned(
        val taskId: String,
        val ok: Boolean,
        val branchDeleted: Boolean,
        val message: String? = null,
    ) : RunnerMessage()
    /** A GitHub token to fetch or push a task's repo. */
    @Serializable
    data class TaskTokenRequest(
        val reqId: String,
        val taskId: String,
        val owner: String,
        val repo: String,
        val purpose: String? = null,
    ) : RunnerMessage()
    /** A repo's secrets: for a task assigned to this machine (`taskId`), or for its owner's own checkout (`maple-runner secrets pull`). */
    @Serializable
    data class SecretsRequest(
        val reqId: String,
        val taskId: String? = null,
        /** GitHub owner/name. */
        val repo: String,
    ) : RunnerMessage()
    /** A message this build doesn't know yet; newer servers and runners may send them. */
    data class Unknown(val type: String) : RunnerMessage()

    object Serializer : WireUnionSerializer<RunnerMessage>("RunnerMessage") {
        override fun decode(json: Json, type: String, body: JsonObject): RunnerMessage = when (type) {
            "hello" -> json.decodeFromJsonElement(Hello.serializer(), body)
            "health" -> json.decodeFromJsonElement(Health.serializer(), body)
            "session.opened" -> json.decodeFromJsonElement(SessionOpened.serializer(), body)
            "session.error" -> json.decodeFromJsonElement(SessionError.serializer(), body)
            "session.ended" -> json.decodeFromJsonElement(SessionEnded.serializer(), body)
            "session.activity" -> json.decodeFromJsonElement(SessionActivity.serializer(), body)
            "session.replay" -> json.decodeFromJsonElement(SessionReplay.serializer(), body)
            "update.status" -> json.decodeFromJsonElement(UpdateStatus.serializer(), body)
            "agent.login_status" -> json.decodeFromJsonElement(AgentLoginStatus.serializer(), body)
            "usage" -> json.decodeFromJsonElement(Usage.serializer(), body)
            "session.cost" -> json.decodeFromJsonElement(SessionCost.serializer(), body)
            "mcp.request" -> json.decodeFromJsonElement(McpRequest.serializer(), body)
            "task.started" -> json.decodeFromJsonElement(TaskStarted.serializer(), body)
            "task.finished" -> json.decodeFromJsonElement(TaskFinished.serializer(), body)
            "task.diff" -> json.decodeFromJsonElement(TaskDiff.serializer(), body)
            "task.merged" -> json.decodeFromJsonElement(TaskMerged.serializer(), body)
            "task.merge_check" -> json.decodeFromJsonElement(TaskMergeCheck.serializer(), body)
            "task.handed_off" -> json.decodeFromJsonElement(TaskHandedOff.serializer(), body)
            "draft.progress" -> json.decodeFromJsonElement(DraftProgress.serializer(), body)
            "draft.done" -> json.decodeFromJsonElement(DraftDone.serializer(), body)
            "task.progress" -> json.decodeFromJsonElement(TaskProgress.serializer(), body)
            "task.cleaned" -> json.decodeFromJsonElement(TaskCleaned.serializer(), body)
            "task.token_request" -> json.decodeFromJsonElement(TaskTokenRequest.serializer(), body)
            "secrets.request" -> json.decodeFromJsonElement(SecretsRequest.serializer(), body)
            else -> Unknown(type)
        }

        override fun encode(json: Json, value: RunnerMessage): Pair<String, JsonElement?> = when (value) {
            is Hello -> "hello" to json.encodeToJsonElement(Hello.serializer(), value)
            is Health -> "health" to json.encodeToJsonElement(Health.serializer(), value)
            is SessionOpened -> "session.opened" to json.encodeToJsonElement(SessionOpened.serializer(), value)
            is SessionError -> "session.error" to json.encodeToJsonElement(SessionError.serializer(), value)
            is SessionEnded -> "session.ended" to json.encodeToJsonElement(SessionEnded.serializer(), value)
            is SessionActivity -> "session.activity" to json.encodeToJsonElement(SessionActivity.serializer(), value)
            is SessionReplay -> "session.replay" to json.encodeToJsonElement(SessionReplay.serializer(), value)
            is UpdateStatus -> "update.status" to json.encodeToJsonElement(UpdateStatus.serializer(), value)
            is AgentLoginStatus -> "agent.login_status" to json.encodeToJsonElement(AgentLoginStatus.serializer(), value)
            is Usage -> "usage" to json.encodeToJsonElement(Usage.serializer(), value)
            is SessionCost -> "session.cost" to json.encodeToJsonElement(SessionCost.serializer(), value)
            is McpRequest -> "mcp.request" to json.encodeToJsonElement(McpRequest.serializer(), value)
            is TaskStarted -> "task.started" to json.encodeToJsonElement(TaskStarted.serializer(), value)
            is TaskFinished -> "task.finished" to json.encodeToJsonElement(TaskFinished.serializer(), value)
            is TaskDiff -> "task.diff" to json.encodeToJsonElement(TaskDiff.serializer(), value)
            is TaskMerged -> "task.merged" to json.encodeToJsonElement(TaskMerged.serializer(), value)
            is TaskMergeCheck -> "task.merge_check" to json.encodeToJsonElement(TaskMergeCheck.serializer(), value)
            is TaskHandedOff -> "task.handed_off" to json.encodeToJsonElement(TaskHandedOff.serializer(), value)
            is DraftProgress -> "draft.progress" to json.encodeToJsonElement(DraftProgress.serializer(), value)
            is DraftDone -> "draft.done" to json.encodeToJsonElement(DraftDone.serializer(), value)
            is TaskProgress -> "task.progress" to json.encodeToJsonElement(TaskProgress.serializer(), value)
            is TaskCleaned -> "task.cleaned" to json.encodeToJsonElement(TaskCleaned.serializer(), value)
            is TaskTokenRequest -> "task.token_request" to json.encodeToJsonElement(TaskTokenRequest.serializer(), value)
            is SecretsRequest -> "secrets.request" to json.encodeToJsonElement(SecretsRequest.serializer(), value)
            is Unknown -> value.type to null
        }
    }
}

/** Server → runner. */
@Serializable(with = ServerToRunner.Serializer::class)
sealed class ServerToRunner {
    @Serializable
    data class SessionOpen(
        val id: String,
        val agent: String,
        val cwd: String,
        val cols: Int,
        val rows: Int,
        val prompt: String? = null,
        /** Continue the agent's last conversation in `cwd` (claude --resume / codex resume). */
        val resume: Boolean,
        val taskId: String? = null,
        val worktree: dev.maplefactory.wire.WorktreeSpec? = null,
        val task: dev.maplefactory.wire.TaskStart? = null,
        val unattended: dev.maplefactory.wire.Unattended? = null,
        val model: String? = null,
        /** The factory's enabled MCP connectors, secrets included. */
        val connectors: List<dev.maplefactory.wire.McpConnector>? = null,
    ) : ServerToRunner()
    @Serializable
    data class SessionResize(
        val id: String,
        val cols: Int,
        val rows: Int,
    ) : ServerToRunner()
    @Serializable
    data class SessionKill(
        val id: String,
    ) : ServerToRunner()
    /** Send the session's screen and scrollback, so a new viewer starts with what's there. */
    @Serializable
    data class SessionReplay(
        val id: String,
        /** Echoed in the reply, so it goes to the viewer that asked. */
        val nonce: String,
    ) : ServerToRunner()
    data object RunnerUpdate : ServerToRunner()
    /** Sign an agent in with a device code (`codex login --device-auth`), or cancel one that's waiting. */
    @Serializable
    data class AgentLogin(
        val agent: String,
        val cancel: Boolean,
    ) : ServerToRunner()
    data object RunnerRestart : ServerToRunner()
    /** The answer to `mcp.request`: `result` ({summary, data}) or `error`. */
    @Serializable
    data class McpResponse(
        val reqId: String,
        val result: JsonElement? = null,
        val error: String? = null,
    ) : ServerToRunner()
    /** Commit what's left in a task's worktree and push its branch. */
    @Serializable
    data class TaskFinish(
        val taskId: String,
        val cwd: String,
        val repoDir: String,
        val branch: String,
        val base: String? = null,
        val title: String,
        /** Push with the machine's own credentials (no GitHub App). */
        val fallback: Boolean,
        /** The repo's checks (commands, one per line) to run in the worktree before committing; any failing stops the finish. */
        val checks: String? = null,
    ) : ServerToRunner()
    /** Report a task's diff against its base (answered with `task.diff`). */
    @Serializable
    data class TaskDiff(
        val taskId: String,
        val cwd: String,
        val base: String,
    ) : ServerToRunner()
    /** Dry-run merging a task's branch into the latest `origin/<base>` (`git merge-tree`), touching nothing (answered with `task.merge_check`). */
    @Serializable
    data class TaskMergeCheck(
        val taskId: String,
        val cwd: String,
        val base: String,
    ) : ServerToRunner()
    /** Merge a task's branch into its base on origin, for repos with no GitHub App. */
    @Serializable
    data class TaskMerge(
        val taskId: String,
        val cwd: String,
        val branch: String,
        val base: String,
        val title: String,
    ) : ServerToRunner()
    /** The task is moving to another machine: commit what its worktree has (as WIP) and push its branch. */
    @Serializable
    data class TaskHandoff(
        val taskId: String,
        val cwd: String,
        val repoDir: String,
        val branch: String,
        val base: String? = null,
        val title: String,
        val fallback: Boolean,
    ) : ServerToRunner()
    /** Run Draft with AI's agent once, unable to change anything: with `repo` or `folder`, in a throwaway worktree of it made from GitHub's copy of `base` (then removed); else in an empty folder with no tools. */
    @Serializable
    data class DraftRun(
        val id: String,
        val agent: String,
        val prompt: String,
        val repo: String? = null,
        val folder: String? = null,
        val base: String? = null,
    ) : ServerToRunner()
    @Serializable
    data class DraftCancel(
        val id: String,
    ) : ServerToRunner()
    /** Remove a finished task's worktree and local branch if nothing would be lost. */
    @Serializable
    data class TaskCleanup(
        val taskId: String,
        val cwd: String,
        val repoDir: String,
        val branch: String,
        val merged: Boolean,
        val heads: List<String> = emptyList(),
        val repo: String? = null,
        /** The repo's worktree scripts: teardown runs first, and archive replaces the removal. */
        val scripts: dev.maplefactory.wire.WorktreeScripts? = null,
        /** Merged, and its branch may still be on origin: delete it there too, if it's one of `heads` or already in the default branch. */
        val deleteRemote: Boolean? = null,
    ) : ServerToRunner()
    /** The answer to `task.token_request`. */
    @Serializable
    data class TaskToken(
        val reqId: String,
        val token: String? = null,
        val error: String? = null,
        val code: String? = null,
    ) : ServerToRunner()
    /** The answer to `secrets.request`: `values` by name, or `error` with a `code`. */
    @Serializable
    data class SecretsReply(
        val reqId: String,
        val values: Map<String, String>? = null,
        val error: String? = null,
        val code: String? = null,
    ) : ServerToRunner()
    /** A message this build doesn't know yet; newer servers and runners may send them. */
    data class Unknown(val type: String) : ServerToRunner()

    object Serializer : WireUnionSerializer<ServerToRunner>("ServerToRunner") {
        override fun decode(json: Json, type: String, body: JsonObject): ServerToRunner = when (type) {
            "session.open" -> json.decodeFromJsonElement(SessionOpen.serializer(), body)
            "session.resize" -> json.decodeFromJsonElement(SessionResize.serializer(), body)
            "session.kill" -> json.decodeFromJsonElement(SessionKill.serializer(), body)
            "session.replay" -> json.decodeFromJsonElement(SessionReplay.serializer(), body)
            "runner.update" -> RunnerUpdate
            "agent.login" -> json.decodeFromJsonElement(AgentLogin.serializer(), body)
            "runner.restart" -> RunnerRestart
            "mcp.response" -> json.decodeFromJsonElement(McpResponse.serializer(), body)
            "task.finish" -> json.decodeFromJsonElement(TaskFinish.serializer(), body)
            "task.diff" -> json.decodeFromJsonElement(TaskDiff.serializer(), body)
            "task.merge_check" -> json.decodeFromJsonElement(TaskMergeCheck.serializer(), body)
            "task.merge" -> json.decodeFromJsonElement(TaskMerge.serializer(), body)
            "task.handoff" -> json.decodeFromJsonElement(TaskHandoff.serializer(), body)
            "draft.run" -> json.decodeFromJsonElement(DraftRun.serializer(), body)
            "draft.cancel" -> json.decodeFromJsonElement(DraftCancel.serializer(), body)
            "task.cleanup" -> json.decodeFromJsonElement(TaskCleanup.serializer(), body)
            "task.token" -> json.decodeFromJsonElement(TaskToken.serializer(), body)
            "secrets.reply" -> json.decodeFromJsonElement(SecretsReply.serializer(), body)
            else -> Unknown(type)
        }

        override fun encode(json: Json, value: ServerToRunner): Pair<String, JsonElement?> = when (value) {
            is SessionOpen -> "session.open" to json.encodeToJsonElement(SessionOpen.serializer(), value)
            is SessionResize -> "session.resize" to json.encodeToJsonElement(SessionResize.serializer(), value)
            is SessionKill -> "session.kill" to json.encodeToJsonElement(SessionKill.serializer(), value)
            is SessionReplay -> "session.replay" to json.encodeToJsonElement(SessionReplay.serializer(), value)
            is RunnerUpdate -> "runner.update" to null
            is AgentLogin -> "agent.login" to json.encodeToJsonElement(AgentLogin.serializer(), value)
            is RunnerRestart -> "runner.restart" to null
            is McpResponse -> "mcp.response" to json.encodeToJsonElement(McpResponse.serializer(), value)
            is TaskFinish -> "task.finish" to json.encodeToJsonElement(TaskFinish.serializer(), value)
            is TaskDiff -> "task.diff" to json.encodeToJsonElement(TaskDiff.serializer(), value)
            is TaskMergeCheck -> "task.merge_check" to json.encodeToJsonElement(TaskMergeCheck.serializer(), value)
            is TaskMerge -> "task.merge" to json.encodeToJsonElement(TaskMerge.serializer(), value)
            is TaskHandoff -> "task.handoff" to json.encodeToJsonElement(TaskHandoff.serializer(), value)
            is DraftRun -> "draft.run" to json.encodeToJsonElement(DraftRun.serializer(), value)
            is DraftCancel -> "draft.cancel" to json.encodeToJsonElement(DraftCancel.serializer(), value)
            is TaskCleanup -> "task.cleanup" to json.encodeToJsonElement(TaskCleanup.serializer(), value)
            is TaskToken -> "task.token" to json.encodeToJsonElement(TaskToken.serializer(), value)
            is SecretsReply -> "secrets.reply" to json.encodeToJsonElement(SecretsReply.serializer(), value)
            is Unknown -> value.type to null
        }
    }
}

/** App (macOS, web) → server. */
@Serializable(with = ClientMessage.Serializer::class)
sealed class ClientMessage {
    /** Start receiving `snapshot` and live updates. */
    data object Subscribe : ClientMessage()
    @Serializable
    data class NoteSave(
        val note: dev.maplefactory.wire.Note,
    ) : ClientMessage()
    /** Fold a request into an existing task: its tickets become the task's context. */
    @Serializable
    data class IntakeAttach(
        val id: String,
        val task: String,
    ) : ClientMessage()
    /** Ask the requester something in their thread. */
    @Serializable
    data class IntakeAsk(
        val id: String,
        val text: String,
    ) : ClientMessage()
    @Serializable
    data class IntakeDecline(
        val id: String,
        val note: String? = null,
    ) : ClientMessage()
    @Serializable
    data class NoteDelete(
        val id: String,
    ) : ClientMessage()
    /** The task this app is showing, if any, for teammates' presence. */
    @Serializable
    data class Presence(
        val viewing: String? = null,
    ) : ClientMessage()
    @Serializable
    data class SessionOpen(
        val machine: String,
        val agent: String,
        val cwd: String,
        val cols: Int,
        val rows: Int,
        val prompt: String? = null,
    ) : ClientMessage()
    /** Stream a session's terminal to this connection, starting with a replay. */
    @Serializable
    data class SessionAttach(
        val machine: String,
        val id: String,
        val cols: Int,
        val rows: Int,
    ) : ClientMessage()
    @Serializable
    data class SessionDetach(
        val id: String,
    ) : ClientMessage()
    @Serializable
    data class SessionResize(
        val machine: String,
        val id: String,
        val cols: Int,
        val rows: Int,
    ) : ClientMessage()
    @Serializable
    data class SessionKill(
        val machine: String,
        val id: String,
    ) : ClientMessage()
    /** The machine's owner or an admin: who else may open this session's terminal, the whole list (empty unshares it). */
    @Serializable
    data class SessionShare(
        val machine: String,
        val id: String,
        val shares: List<dev.maplefactory.wire.ShareGrant> = emptyList(),
    ) : ClientMessage()
    @Serializable
    data class GoalSave(
        val goal: dev.maplefactory.wire.Goal,
    ) : ClientMessage()
    /** Draft with AI: turn `idea` into a task. `id` is the app's own (a UUID), for its `draft.updated`s. */
    @Serializable
    data class DraftStart(
        val id: String,
        val idea: String,
        val goal: String? = null,
        val agent: String? = null,
    ) : ClientMessage()
    /** Carry on a draft with this goal (one it suggested making, or another). */
    @Serializable
    data class DraftGoal(
        val id: String,
        val goal: String,
    ) : ClientMessage()
    @Serializable
    data class DraftCancel(
        val id: String,
    ) : ClientMessage()
    /** Run Scout on a goal: its leftovers still worth doing come back as drafted plans. */
    @Serializable
    data class GoalScout(
        val goal: String,
    ) : ClientMessage()
    /** Admins only: run Set up with AI on a repo; its suggestion comes back in `repo.setup.updated`. */
    @Serializable
    data class RepoSetupStart(
        val repo: String,
        /** claude or codex; none: whichever the machine has. */
        val agent: String? = null,
    ) : ClientMessage()
    /** Stop a repo's Set up with AI run. */
    @Serializable
    data class RepoSetupCancel(
        val repo: String,
    ) : ClientMessage()
    /** Follow a goal (it's in your sidebar) or stop following it. */
    @Serializable
    data class GoalFollow(
        val id: String,
        val following: Boolean,
    ) : ClientMessage()
    /** Its lead or an admin. With unfinished tasks it needs `unfinished`, to say what happens to them. */
    @Serializable
    data class GoalArchive(
        val id: String,
        val archived: Boolean,
        val unfinished: dev.maplefactory.wire.UnfinishedTasks? = null,
    ) : ClientMessage()
    /** Its owner or an admin. */
    @Serializable
    data class MachineSettings(
        val machine: String,
        val settings: dev.maplefactory.wire.MachineSettings,
        /** When pausing: checkpoint teammates' tasks running here and move them to other machines. */
        val handOff: Boolean? = null,
    ) : ClientMessage()
    /** Its owner or an admin: a nickname shown everywhere in place of its id. Empty goes back to the id. */
    @Serializable
    data class MachineRename(
        val machine: String,
        val name: String,
    ) : ClientMessage()
    /** Its owner or an admin: update its runner to the latest release now. */
    @Serializable
    data class MachineUpdate(
        val machine: String,
    ) : ClientMessage()
    /** Its owner only: sign one of its agents in (answered with `machine.agent_login`), or cancel that. */
    @Serializable
    data class MachineAgentLogin(
        val machine: String,
        val agent: String,
        val cancel: Boolean? = null,
    ) : ClientMessage()
    /** Look for a newer runner release now, skipping the cache. Only looks: it never installs anything. Answers with `runner.released` (when the feed changed) and a toast naming the machine. */
    @Serializable
    data class RunnerCheck(
        val machine: String,
    ) : ClientMessage()
    /** Admins only. */
    @Serializable
    data class PolicySave(
        val policy: dev.maplefactory.wire.RiskPolicy,
    ) : ClientMessage()
    /** Admins only: the org's prompt additions. */
    @Serializable
    data class PromptsSave(
        val prompts: dev.maplefactory.wire.PromptAdditions,
    ) : ClientMessage()
    /** Admins only: make someone who has signed in an admin of this factory. */
    @Serializable
    data class AdminsGrant(
        val login: String,
    ) : ClientMessage()
    /** Admins only: take back an admin grant (not a GitHub owner's, nor your own). */
    @Serializable
    data class AdminsRevoke(
        val login: String,
    ) : ClientMessage()
    /** Admins only: cut someone off now. Their app tokens and web sessions stop working, their apps and terminals close; they can sign in again if GitHub still lets them (not a GitHub owner, nor yourself). */
    @Serializable
    data class MembersRevoke(
        val login: String,
    ) : ClientMessage()
    /** Admins only: the factory's MCP connectors, the whole list. A blank secret value keeps the stored one. */
    @Serializable
    data class ConnectorsSave(
        val connectors: List<dev.maplefactory.wire.McpConnector> = emptyList(),
    ) : ClientMessage()
    /** Admins only: one integration's settings. A blank secret value keeps the stored one. */
    @Serializable
    data class IntegrationsSave(
        val kind: dev.maplefactory.wire.IntegrationKind,
        val enabled: Boolean,
        val values: Map<String, String> = emptyMap(),
    ) : ClientMessage()
    /** Read the repos the GitHub App is installed on again. */
    data object ReposRefresh : ClientMessage()
    /** Admins only: a repo the GitHub App doesn't list (or there's no app). */
    @Serializable
    data class ReposAdd(
        val name: String,
    ) : ClientMessage()
    /** Admins only: one added by hand. */
    @Serializable
    data class ReposRemove(
        val name: String,
    ) : ClientMessage()
    /** Admins only: the other GitHub accounts (orgs or users) whose installations of the app add repos, besides the factory's own. Replaces the list, then reads the repos again. */
    @Serializable
    data class ReposOwnersSet(
        /** GitHub logins. */
        val owners: List<String> = emptyList(),
    ) : ClientMessage()
    /** Admins only: add or replace one of a repo's secrets. The value is never sent back to any app. */
    @Serializable
    data class SecretsSet(
        val repo: String,
        val name: String,
        val value: String,
    ) : ClientMessage()
    /** Admins only. */
    @Serializable
    data class SecretsDelete(
        val repo: String,
        val name: String,
    ) : ClientMessage()
    /** Admins only: replace a repo's worktree scripts (and its prompt additions). Blank commands are cleared; all blank removes them. */
    @Serializable
    data class ReposScriptsSet(
        val repo: String,
        val scripts: dev.maplefactory.wire.WorktreeScripts,
        /** The repo's prompt additions; none (an older app) keeps the stored ones. */
        val prompts: dev.maplefactory.wire.PromptAdditions? = null,
    ) : ClientMessage()
    /** Let the factory auto-merge a goal's work up to `upTo`; none takes it back. */
    @Serializable
    data class GoalAcceptRisk(
        val goal: String,
        val upTo: dev.maplefactory.wire.RiskLevel? = null,
        val note: String? = null,
    ) : ClientMessage()
    @Serializable
    data class TaskCreate(
        val goal: String,
        val title: String,
        val brief: String,
        val shareable: Boolean,
        /** Send it to planning now; otherwise it stays a draft. */
        val plan: Boolean,
        val tickets: List<dev.maplefactory.wire.TicketLink> = emptyList(),
        val agent: String? = null,
        /** The request it was composed from, which then tracks it. */
        val intake: String? = null,
        val repo: String? = null,
        val after: List<String>? = null,
        val effort: String? = null,
        val priority: dev.maplefactory.wire.Priority? = null,
    ) : ClientMessage()
    @Serializable
    data class TaskEdit(
        val id: String,
        val title: String? = null,
        val brief: String? = null,
        val shareable: Boolean? = null,
        val repo: String? = null,
        /** Put it in this effort; an empty string takes it out. */
        val effort: String? = null,
        /** claude or codex; refused once it's merged or cancelled. Takes effect from its next session. */
        val agent: String? = null,
        /** The model its next sessions use; an empty string goes back to the agent's default. */
        val model: String? = null,
        /** Set its priority; refused once it's merged or cancelled. Setting a queued task to P0 moves it to the front of the queue. */
        val priority: dev.maplefactory.wire.Priority? = null,
        /** Take its priority off. */
        val clearPriority: Boolean? = null,
    ) : ClientMessage()
    /** Turn a reviewing or merged task's leftover review findings (or a note) into draft tasks in its goal, each linked back by `followUpOf`. Nothing is made if any item is refused. */
    @Serializable
    data class TaskFollowUp(
        val id: String,
        val items: List<dev.maplefactory.wire.FollowUpItem> = emptyList(),
    ) : ClientMessage()
    /** Change who owns it: anyone can take a task for themselves; only its owner or an admin can hand it to someone else. Its open hand goes with it, and its next sessions prefer the new owner's machines (one already running keeps its machine, as a team slot). */
    @Serializable
    data class TaskAssign(
        val id: String,
        /** The member's login. */
        val owner: String,
    ) : ClientMessage()
    /** Send a draft to planning, or pick up a backlog task (one with a plan is planned again). */
    @Serializable
    data class TaskPlan(
        val id: String,
    ) : ClientMessage()
    /** Park a draft or a plan waiting for approval in the backlog: nothing runs on it until someone picks it up. */
    @Serializable
    data class TaskBacklog(
        val id: String,
    ) : ClientMessage()
    @Serializable
    data class TaskComment(
        val id: String,
        val text: String,
        val anchor: String? = null,
    ) : ClientMessage()
    /** A change request for the planner or builder. */
    @Serializable
    data class TaskSteer(
        val id: String,
        val text: String,
        val anchor: String? = null,
    ) : ClientMessage()
    /** Submit a review of its diff: each note goes to its comments, and the batch to the planner or builder as one change request. */
    @Serializable
    data class TaskReview(
        val id: String,
        val notes: List<dev.maplefactory.wire.ReviewNote> = emptyList(),
        val summary: String? = null,
    ) : ClientMessage()
    /** Approve its plan; a planned backlog task is picked up and builds once its approvals are met. */
    @Serializable
    data class TaskApprovePlan(
        val id: String,
        /** Turn down the plan's suggested title and keep the current one. */
        val keepTitle: Boolean? = null,
    ) : ClientMessage()
    /** Answer the agent's question. */
    @Serializable
    data class TaskAnswer(
        val id: String,
        val text: String,
    ) : ClientMessage()
    /** Answer the permission prompt the task's agent is waiting on, in its session. Refused unless its activity is waiting with a `permission` question. */
    @Serializable
    data class TaskAnswerPrompt(
        val id: String,
        val choice: dev.maplefactory.wire.PromptChoice,
    ) : ClientMessage()
    @Serializable
    data class TaskResolveHand(
        val id: String,
        val option: String? = null,
        val note: String,
    ) : ClientMessage()
    @Serializable
    data class TaskApproveChanges(
        val id: String,
    ) : ClientMessage()
    @Serializable
    data class TaskMerge(
        val id: String,
    ) : ClientMessage()
    /** Stop the auto-merge counting down on a task; a person merges it instead. */
    @Serializable
    data class TaskHoldMerge(
        val id: String,
    ) : ClientMessage()
    @Serializable
    data class TaskCancel(
        val id: String,
    ) : ClientMessage()
    @Serializable
    data class TaskRetry(
        val id: String,
    ) : ClientMessage()
    /** Reorder or schedule a task's place in the queue for sessions. A draft is sent to planning. */
    @Serializable
    data class TaskQueue(
        val id: String,
        /** Move it ahead of this task; "top": the front of the queue. None moves it to the back, unless startAt or clearSchedule is given (they keep its place). */
        val before: String? = null,
        /** Hold it until then (ms). */
        val startAt: Long? = null,
        /** Start it as soon as there's room. */
        val clearSchedule: Boolean? = null,
        /** Start its next session now, over the machine's slot count. */
        val force: Boolean? = null,
    ) : ClientMessage()
    /** Reorder a draft among its goal's drafts; it stays a draft. */
    @Serializable
    data class TaskRankDraft(
        val id: String,
        /** Move it ahead of this draft; "top": the first draft. None moves it to the bottom. */
        val before: String? = null,
    ) : ClientMessage()
    /** Run the pull request's failed CI checks again. */
    @Serializable
    data class TaskRerunChecks(
        val id: String,
    ) : ClientMessage()
    /** Run one of the pull request's CI checks again, by name. */
