    @Serializable
    data class TaskCheckLog(
        val id: String,
        val check: String,
    ) : ClientMessage()
    /** Splits an over-budget task: it keeps its first steps (up to the one it's on), the rest become `parts - 1` new tasks that are planned on their own. */
    @Serializable
    data class TaskSplit(
        val id: String,
