/** Server → app. */
@Serializable(with = ServerToClient.Serializer::class)
sealed class ServerToClient {
    @Serializable
    data class Snapshot(
        val org: String,
        val me: dev.maplefactory.wire.Member,
        val members: List<dev.maplefactory.wire.Member> = emptyList(),
        val machines: List<dev.maplefactory.wire.Machine> = emptyList(),
        /** The most recent session ends (last 7 days, newest first). */
        val ended: List<dev.maplefactory.wire.EndedSession> = emptyList(),
        val goals: List<dev.maplefactory.wire.Goal> = emptyList(),
        val tasks: List<dev.maplefactory.wire.Task> = emptyList(),
        val policy: dev.maplefactory.wire.RiskPolicy,
