        val prompts: dev.maplefactory.wire.PromptAdditions? = null,
        /** The factory's MCP connectors, secret values blank. None: an older server. */
        val connectors: List<dev.maplefactory.wire.McpConnector>? = null,
        /** Slack, Linear and Jira: their status, secret values blank. None: an older server. */
        val integrations: List<dev.maplefactory.wire.Integration>? = null,
        val online: List<dev.maplefactory.wire.Presence> = emptyList(),
        val notes: List<dev.maplefactory.wire.Note> = emptyList(),
        val follows: List<dev.maplefactory.wire.GoalFollow> = emptyList(),
        val intake: List<dev.maplefactory.wire.IntakeRequest> = emptyList(),
        val repos: List<dev.maplefactory.wire.OrgRepo> = emptyList(),
