        /** Each goal's latest Scout run. None: an older server. */
        val scoutRuns: List<dev.maplefactory.wire.ScoutRun>? = null,
        /** The newest released runner version, when there's a release. */
        val runnerLatest: String? = null,
        /** Runner releases, newest first, with their notes (What's new). None: an older server. */
        val runnerReleases: List<dev.maplefactory.wire.RunnerRelease>? = null,
        /** This factory's maple-server version. */
        val serverVersion: String? = null,
        /** A newer maple-server, when there is one (told to admins only). */
        val serverUpdate: dev.maplefactory.wire.ServerUpdate? = null,
        /** GitHub's incident or degraded components, from githubstatus.com. None: all clear, not checked yet, or an older server. */
        val githubStatus: dev.maplefactory.wire.GitHubStatus? = null,
